package com.rulecraft.decisionops.decisionapi.api;import com.rulecraft.decisionops.decisionapi.ApiCredentialService;import com.rulecraft.decisionops.decisionapi.ApiCredentialService.*;import com.rulecraft.decisionops.identity.security.CurrentUser;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/api-credentials") public class ApiCredentialController {private final ApiCredentialService service;public ApiCredentialController(ApiCredentialService service){this.service=service;}@GetMapping List<CredentialView> list(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication auth){return service.list(CurrentUser.require(auth),projectId,serviceId);}@PostMapping @ResponseStatus(HttpStatus.CREATED)CreatedCredential create(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody CreateCredential body,Authentication auth){return service.create(CurrentUser.require(auth),projectId,serviceId,body);}@PostMapping("/{credentialId}/revoke")CredentialView revoke(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID credentialId,@RequestBody RevokeCredential body,Authentication auth){return service.revoke(CurrentUser.require(auth),projectId,serviceId,credentialId,body);}}
